import java.util.List;

interface Formatter {
    String format(List<String> rows);
}

class CsvFormatter implements Formatter {
    public String format(List<String> rows) { return String.join(",", rows); }
}

class BulletFormatter implements Formatter {
    public String format(List<String> rows) {
        StringBuilder sb = new StringBuilder();
        for (String r : rows) sb.append("- ").append(r).append('\n');
        return sb.toString();
    }
}

class ReportService {
    private final Formatter formatter;            // HAS a formatter.
    ReportService(Formatter formatter) { this.formatter = formatter; }
    String build(List<String> rows) {
        return formatter.format(rows);            // delegate formatting.
    }
}

public class Reports {
    public static void main(String[] args) {
        List<String> rows = List.of("pen", "ink");
        System.out.println(new ReportService(new CsvFormatter()).build(rows));     // pen,ink
        System.out.print(new ReportService(new BulletFormatter()).build(rows));  // - pen / - ink
    }
}
